package com.softeno.template.sample.http.internal.coroutine

import com.softeno.template.sample.http.internal.SampleResponseDto
import com.softeno.template.testsupport.BaseIntegrationTest
import com.softeno.template.testsupport.R
import org.junit.jupiter.api.Test
import org.springframework.http.MediaType

/**
 * Annotated coroutine controller demo of the /sample endpoints — every payload
 * is generated by [R] and asserted from the same reference.
 */
class SampleControllerIT : BaseIntegrationTest() {

    @Test
    fun `should return id on GET`() {
        val id = R.data()

        webTestClient.get().uri("/sample/$id")
            .exchange()
            .expectStatus().isOk()
            .expectBody().jsonPath("data").isEqualTo(id)
    }

    @Test
    fun `should echo body on POST`() {
        val request = SampleResponseDto(R.data())

        webTestClient.post().uri("/sample")
            .contentType(MediaType.APPLICATION_JSON)
            .bodyValue(request)
            .exchange()
            .expectStatus().isOk()
            .expectBody().jsonPath("data").isEqualTo(request.data)
    }

    @Test
    fun `should echo body on PUT`() {
        val request = SampleResponseDto(R.data())

        webTestClient.put().uri("/sample/${R.data()}")
            .contentType(MediaType.APPLICATION_JSON)
            .bodyValue(request)
            .exchange()
            .expectStatus().isOk()
            .expectBody().jsonPath("data").isEqualTo(request.data)
    }

    @Test
    fun `should accept DELETE`() {
        webTestClient.delete().uri("/sample/${R.data()}")
            .exchange()
            .expectStatus().isOk()
    }
}
